/** The canonical specialist-to-editor writer. Receipts, project visits and
 * signed-in account scope are confirmed before content or navigation proceeds. */
import { apiRequest, ApiRequestError, redactInternals, serverMessage } from '@/lib/queryClient';
import { authService } from '@/services/portal/authService';
import { unboundNotice } from './governanceNotice';
import { captureShellProjectGuard, shellProgramId } from './shellProject';
import { setEditorTarget } from './editorTarget';
import { useAuthoringHandoffController } from './authoringHandoffRecovery';
import { hasAuthoringCreationOutcome, readAuthoringCreationRecovery, type AuthoringCreationRecoveryIdentity } from './editor/authoringCreationRecovery';
export type { AuthoringHandoffController, AuthoringHandoffRecoveryState } from './authoringHandoffRecovery';

export interface AuthoringHandoff {
  title: string;
  /** The specialist states its own CTD module; the server otherwise defaults to M3. */
  module: string;
  /** A working identifier, never a guessed CTD filing location. */
  code: string;
  content: string;
  subject: string;
}
export interface HandoffContext {
  programId: string | null;
  code: string;
  isCurrent: () => boolean;
}
export type AuthoringHandoffResult = HandoffContext & (
  | { ok: true; docId: string; programId: string; bound: boolean | null; message: string; reused?: boolean }
  | { ok: false; phase: 'refused' | 'unknown' | 'partial' | 'stale' | 'blocked'; docId?: string; message: string }
);
type StageResult =
  | { phase: 'confirmed'; body: Record<string, unknown>; row: Record<string, unknown> }
  | { phase: 'refused' | 'unknown' | 'stale'; message?: string; recovery?: AuthoringCreationRecoveryIdentity };
const nonempty = (value: unknown): value is string => typeof value === 'string' && Boolean(value.trim());
const record = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;

function captureHandoffContext(code: string, mounted: () => boolean): HandoffContext {
  const programId = shellProgramId();
  const projectCurrent = captureShellProjectGuard();
  const session = authService.captureSessionReadGuard();
  const account = authService.getUser();
  const actor = `${account?.organizationId ?? ''}:${account?.id ?? ''}`;
  return { programId, code, isCurrent: () => mounted() && projectCurrent() && session.sameRevision()
    && `${authService.getUser()?.organizationId ?? ''}:${authService.getUser()?.id ?? ''}` === actor };
}

function confirmedStage(kind: 'document' | 'section', raw: unknown, request: Record<string, unknown>): StageResult {
  const body = record(raw);
  const row = record(body?.[kind]);
  if (body?.success !== true || !row || !nonempty(row.id) || typeof row.title !== 'string') return { phase: 'unknown' };
  const matches = kind === 'document' ? row.client_program_id === request.client_program_id
    : row.doc_id === request.doc_id && row.code === request.code;
  return matches ? { phase: 'confirmed', body, row } : { phase: 'unknown' };
}

async function writeHandoffStage(kind: 'document' | 'section', request: Record<string, unknown>, current: () => boolean): Promise<StageResult> {
  try {
    const response = await apiRequest('POST', kind === 'document' ? '/api/authoring/docs' : '/api/authoring/sections', request);
    if (!current()) return { phase: 'stale' };
    const body: unknown = await response.json().catch(() => null);
    if (!current()) return { phase: 'stale' };
    if (kind === 'document' && hasAuthoringCreationOutcome(body)) return recoveryStage(body, request);
    if (!response.ok) return { phase: response.status >= 400 && response.status < 500 ? 'refused' : 'unknown', message: response.status === 401 ? 'your session isn’t authenticated' : serverMessage(body) ?? undefined };
    return confirmedStage(kind, body, request);
  } catch (error) {
    if (!current()) return { phase: 'stale' };
    if (kind === 'document' && error instanceof ApiRequestError && hasAuthoringCreationOutcome(error.payload)) return recoveryStage(error.payload, request);
    return error instanceof ApiRequestError && error.status >= 400 && error.status < 500
      ? { phase: 'refused', message: redactInternals(error.message, 'The server refused this write.') } : { phase: 'unknown' };
  }
}

function recoveryStage(body: unknown, request: Record<string, unknown>): StageResult {
  const recovery = readAuthoringCreationRecovery(body, authService.getUser()?.organizationId,
    typeof request.client_program_id === 'string' ? request.client_program_id : null);
  return { phase: 'unknown', ...(recovery ? { recovery } : {}) };
}

function failedHandoff(context: HandoffContext, result: Exclude<StageResult, { phase: 'confirmed' }>, subject: string, docId?: string): AuthoringHandoffResult {
  if (result.recovery && !docId) return { ...context, ok: false, phase: 'unknown', docId: result.recovery.documentId,
    message: `Document ${result.recovery.documentId}: ${result.recovery.creationOutcome === 'committed' ? 'creation committed, but its current handoff could not be confirmed' : 'creation outcome is unconfirmed'}. Check this exact document in its original project before continuing. Do not retry creation; ${subject} is still here.` };
  const known = docId ? `Document ${docId} was created, but its text` : 'The document';
  if (result.phase === 'stale') return { ...context, ok: false, phase: 'stale', ...(docId ? { docId } : {}),
    message: 'The project or signed-in account changed while the handoff was running. Check working documents in the original project before creating another copy.' };
  if (result.phase === 'refused') return { ...context, ok: false, phase: docId ? 'partial' : 'refused', ...(docId ? { docId } : {}),
    message: docId ? `${known} did not save — ${result.message ?? 'the server refused the text write'}. Staying here so you do not lose ${subject}. Check that document before retrying.`
      : `Couldn’t create the document — ${result.message ?? 'the server refused it'}. Nothing was saved; ${subject} is still here.` };
  return { ...context, ok: false, phase: 'unknown', ...(docId ? { docId } : {}),
    message: docId ? `${known} save could not be confirmed. Check that document in the original project before creating another copy; ${subject} is still here.`
      : `Could not confirm whether the document was saved. Check working documents in the original project before creating another copy; ${subject} is still here.` };
}

function bindingOutcome(body: Record<string, unknown>): boolean | null {
  const governance = record(body.governance);
  if (governance?.bound === false) return false;
  return governance?.bound === true && nonempty(governance.c2cDocumentId) ? true : null;
}

/** No automatic retry: a missing response can follow a committed write. The
 * existing two-request path can leave a document without a confirmed section. */
export async function saveToAuthoring(h: AuthoringHandoff, mounted: () => boolean = () => true): Promise<AuthoringHandoffResult> {
  const context = captureHandoffContext(h.code, mounted);
  if (!context.programId) return { ...context, ok: false, phase: 'refused',
    message: `Not opened — open a project first: a document belongs to a project. Nothing was saved; ${h.subject} is still here.` };
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject);
  const created = await writeHandoffStage('document', {
    title: h.title, module: h.module, client_program_id: context.programId,
  }, context.isCurrent);
  if (created.phase !== 'confirmed') return failedHandoff(context, created, h.subject);
  const docId = String(created.row.id);
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  const saved = await writeHandoffStage('section', {
    doc_id: docId, code: h.code, title: h.title, content: h.content,
  }, context.isCurrent);
  if (saved.phase !== 'confirmed') return failedHandoff(context, saved, h.subject, docId);
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  return { ...context, ok: true, programId: context.programId, docId, bound: bindingOutcome(created.body),
    message: `Saved to the authoring store as “${h.title}” — open Document authoring to edit it.` + unboundNotice(created.body.governance) };
}

/** Explicit continuation into an already confirmed document; callers verify
 * its current project membership and section inventory before invoking it. */
async function continueAuthoringText(h: AuthoringHandoff, context: HandoffContext, docId: string): Promise<AuthoringHandoffResult> {
  if (!context.isCurrent()) return failedHandoff(context, { phase: 'stale' }, h.subject, docId);
  const saved = await writeHandoffStage('section', { doc_id: docId, code: h.code, title: h.title, content: h.content }, context.isCurrent);
  if (saved.phase !== 'confirmed') return failedHandoff(context, saved, h.subject, docId);
  return { ...context, ok: true, programId: context.programId!, docId, bound: null,
    message: `Text saved to the existing working document “${h.title}”. Filing binding was not rechecked.` };
}

/** All specialist actions in this mounted owner share one attempt lane. */
export function useAuthoringHandoff() {
  return useAuthoringHandoffController({ save: saveToAuthoring, capture: captureHandoffContext, continueText: continueAuthoringText });
}

/** Use the existing exact-target channel; a stale receipt never changes it. */
export function openSavedAuthoring(result: AuthoringHandoffResult, onNav: (id: string) => void): boolean {
  if (!result.ok || !result.isCurrent()) return false;
  setEditorTarget({ docType: null, docId: result.docId, programId: result.programId, code: result.code });
  onNav('document-authoring');
  return true;
}

export type { WorkflowImportSource } from '@shared/authoring/source-import';
import type { AuthoringImportOrigin, AuthoringImportSource, AuthoringSourceImportData, AuthoringSourceImportPreviewData,
  BinaryImportOrigin, BinaryImportSource, WorkflowImportOrigin, WorkflowImportSource } from '@shared/authoring/source-import';
import { agencyResponseImportId, studyDesignImportId } from '@shared/authoring/source-import';
import { stableStringify } from '@shared/canonical-json';
import { authoringCurrentReadPath } from './editor/authoringCurrentRead';

export type SourceImportResult = AuthoringSourceImportData;
export interface SourceIntakeRequest {
  actor: { userId: number; organizationId: number };
  headers: Record<string, string>;
  current: () => boolean;
}
export interface SourceIntakeFailure {
  ok: false;
  phase: 'refused' | 'unknown' | 'stale';
  message: string;
  recovery?: AuthoringCreationRecoveryIdentity;
  identifiedOutcome?: boolean;
}
export type SourceIntakeReply<T> = { ok: true; data: T } | SourceIntakeFailure;
export interface SourceImportInspectionAttempt {
  preview?: AuthoringSourceImportPreviewData;
  recovery?: AuthoringCreationRecoveryIdentity;
  identifiedOutcome?: boolean;
}
export type SourceImportInspection = { ok: true; inventory: Array<{ id: string; title: string }>; data?: SourceImportResult } | SourceIntakeFailure;

export function isWorkflowSource(source: unknown): source is WorkflowImportSource {
  if (!source || typeof source !== 'object') return false;
  const kind = (source as { kind?: unknown }).kind;
  return kind === 'protocol' || kind === 'csr' || kind === 'ivd-assessment' || kind === 'ivd-document' || kind === 'study-design-crf' || kind === 'agency-response';
}

/** Stable selection identity; ordering does not change a CSR selection. */
export function workflowSourceKey(source: WorkflowImportSource): string {
  if (source.kind === 'agency-response') return `agency-response:${agencyResponseImportId(source.eventId, source.questionId) ?? 'invalid-selection'}`;
  if (source.kind === 'study-design-crf') return `${source.kind}:${source.studyId}`;
  if (source.kind !== 'csr') return `${source.kind}:${source.documentId}`;
  if (source.sectionNumbers !== undefined && (!Array.isArray(source.sectionNumbers) || !source.sectionNumbers.every(s => typeof s === 'string'))) return 'invalid-selection';
  return `csr:${source.jobId}:${[...new Set(source.sectionNumbers?.map(s => s.trim()) ?? [])].sort().join(',')}`;
}
const importHash = (value: unknown): value is string => typeof value === 'string' && /^[a-f0-9]{64}$/i.test(value);
const importUuid = (value: unknown): value is string => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const importInteger = (value: unknown): value is number => Number.isSafeInteger(value) && Number(value) > 0 && Number(value) <= 2147483647;
const stringList = (value: unknown): value is string[] => Array.isArray(value) && value.every(s => typeof s === 'string');
const nullableText = (value: unknown): boolean => value === null || typeof value === 'string';
const nullableUuid = (value: unknown): boolean => value === null || importUuid(value);
const nullableInteger = (value: unknown): boolean => value === null || importInteger(value);
const uniqueCodes = (rows: Array<{ code: string }>): boolean => new Set(rows.map(row => row.code.trim().toUpperCase())).size === rows.length;

function validWorkflowSource(source: unknown): source is WorkflowImportSource {
  if (!isWorkflowSource(source)) return false;
  if (source.kind === 'agency-response') return agencyResponseImportId(source.eventId, source.questionId) !== null;
  if (source.kind === 'study-design-crf') return nonempty(source.studyId) && studyDesignImportId(source.studyId) === source.studyId;
  if (source.kind === 'protocol') return importInteger(source.documentId);
  if (source.kind !== 'csr') return importUuid(source.documentId);
  return importInteger(source.jobId) && (source.sectionNumbers === undefined || (Array.isArray(source.sectionNumbers)
    && source.sectionNumbers.length > 0 && source.sectionNumbers.length <= 200 && source.sectionNumbers.every(nonempty)));
}
function validBinarySource(source: unknown): source is BinaryImportSource {
  const value = record(source);
  return value?.kind === 'vault' ? importUuid(value.documentId) : value?.kind === 'data-room' && importInteger(value.sourceId);
}
function validSectionOrigin(section: WorkflowImportOrigin['sectionOrigins'][number]): boolean {
  return !!section && nonempty(section.code) && importHash(section.contentSha256) && nonempty(section.sourceRowId)
    && ['machine', 'template', 'unknown'].includes(section.originalAuthorship)
    && ['unrecorded', 'recorded-name-only'].includes(section.modelEvidence) && nullableText(section.model);
}
const workflowConversions: Record<WorkflowImportSource['kind'], WorkflowImportOrigin['conversion']> = {
  'agency-response': 'agency-response-snapshot',
  'study-design-crf': 'study-design-crf-projection',
  protocol: 'protocol-structure', csr: 'ich-e3-sections', 'ivd-assessment': 'ivd-assessment-snapshot', 'ivd-document': 'ivd-document-snapshot',
};
function validWorkflowScope(origin: WorkflowImportOrigin): boolean {
  const scope = origin.sourceScope;
  return !!scope && ['organization', 'program', 'project'].includes(scope.level)
    && nullableUuid(scope.programId) && nullableInteger(scope.projectId);
}
function validWorkflowMetadata(origin: WorkflowImportOrigin): boolean {
  return nullableText(origin.version) && origin.documentType === null && origin.sectionCode === null
    && origin.conversion === workflowConversions[origin.kind] && validWorkflowScope(origin)
    && !!origin.association && ['recorded', 'explicit'].includes(origin.association.mode) && nullableText(origin.association.reason);
}
function validWorkflowOrigins(origin: WorkflowImportOrigin): boolean {
  return Array.isArray(origin.sectionOrigins) && origin.sectionOrigins.length > 0 && origin.sectionOrigins.every(validSectionOrigin)
    && uniqueCodes(origin.sectionOrigins) && stringList(origin.gaps) && validWorkflowMetadata(origin);
}
export function workflowOriginMatches(origin: WorkflowImportOrigin | undefined, programId: string, source: WorkflowImportSource | undefined): boolean {
  if (!origin || !importUuid(programId) || !validWorkflowSource(source) || origin.kind !== source.kind || origin.programId !== programId) return false;
  const id = source.kind === 'agency-response' ? agencyResponseImportId(source.eventId, source.questionId)
    : source.kind === 'csr' ? source.jobId : source.kind === 'study-design-crf' ? source.studyId : source.documentId;
  if (origin.id !== String(id) || !validWorkflowSource(origin.selection) || workflowSourceKey(origin.selection) !== workflowSourceKey(source)) return false;
  return importHash(origin.fingerprint) && nonempty(origin.title) && validWorkflowOrigins(origin);
}
function validPreviewSections(sections: AuthoringSourceImportPreviewData['sections']): boolean {
  return Array.isArray(sections) && sections.length > 0 && sections.every(s => !!s && nonempty(s.code)
    && typeof s.title === 'string' && importHash(s.contentSha256)) && uniqueCodes(sections);
}
function matchingPreviewScope(data: AuthoringSourceImportPreviewData, programId: string): boolean {
  const association = data.association;
  if (data.fingerprint !== data.origin.fingerprint || data.target?.programId !== programId || !importInteger(data.target.projectId)) return false;
  return !!association && association.targetProgramId === programId && association.mode === data.origin.association.mode
    && typeof association.required === 'boolean' && typeof association.reasonRequired === 'boolean'
    && nullableUuid(association.sourceProgramId) && nullableInteger(association.sourceProjectId);
}
export function readWorkflowPreview(body: unknown, programId: string, source: WorkflowImportSource): AuthoringSourceImportPreviewData | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportPreviewData } | null;
  const data = envelope?.data;
  if (envelope?.success !== true || !data || data.preview !== true || !workflowOriginMatches(data.origin, programId, source)) return null;
  if (!matchingPreviewScope(data, programId) || !validPreviewSections(data.sections) || !stringList(data.gaps) || !stringList(data.warnings)) return null;
  const origins = new Map(data.origin.sectionOrigins.map(section => [section.code.trim().toUpperCase(), section.contentSha256]));
  return origins.size === data.sections.length && data.sections.every(section => origins.get(section.code.trim().toUpperCase()) === section.contentSha256) ? data : null;
}
function validSavedSectionKeys(sections: AuthoringSourceImportData['sections']): boolean {
  if (!sections.every(s => !!s && importUuid(s.id) && nonempty(s.code))) return false;
  const ids = new Set(sections.map(s => String(s.id).toLowerCase()));
  const codes = new Set(sections.map(s => String(s.code).trim().toUpperCase()));
  return ids.size === sections.length && codes.size === sections.length;
}
function actualSavedSection(section: Record<string, unknown>, doc: AuthoringSourceImportData['doc']): boolean {
  return section.doc_id === doc.id && section.tenant_id === doc.tenant_id && typeof section.title === 'string'
    && (typeof section.content === 'string' || section.content === null)
    && Number.isSafeInteger(section.order_index) && Number(section.order_index) >= 0 && Number(section.order_index) <= 2147483647;
}
function validSavedCopy(data: AuthoringSourceImportData | undefined, programId: string): data is AuthoringSourceImportData {
  const doc = data?.doc;
  if (!doc || !importUuid(doc.id) || !nonempty(doc.title) || doc.client_program_id !== programId || !importInteger(doc.tenant_id)) return false;
  return !!data && typeof data.reused === 'boolean' && stringList(data.warnings) && Array.isArray(data.sections) && (data.reused || data.sections.length > 0)
    && validSavedSectionKeys(data.sections) && data.sections.every(section => actualSavedSection(section, doc));
}
function savedSectionsMatch(data: AuthoringSourceImportData, preview: AuthoringSourceImportPreviewData): boolean {
  const codes = new Set(preview.sections.map(s => s.code.trim().toUpperCase()));
  return data.sections.length === codes.size && data.sections.every(section => codes.has(String(section.code).trim().toUpperCase()));
}
const originFields = ['kind', 'id', 'programId', 'title', 'documentType', 'sectionCode', 'conversion'];
const workflowOriginFields = [...originFields, 'fingerprint', 'selection', 'gaps', 'version', 'sourceScope', 'association', 'sectionOrigins'];
const binaryOriginFields = [...originFields, 'fileName', 'mimeType', 'sha256'];
function sameRecordedOrigin(stored: AuthoringImportOrigin, returned: AuthoringImportOrigin, fields: string[]): boolean {
  const project = (origin: AuthoringImportOrigin) => Object.fromEntries(fields.map(key => [key, (origin as unknown as Record<string, unknown>)[key]]));
  return stableStringify(project(stored)) === stableStringify(project(returned));
}
function recordedWorkflowMatches(data: AuthoringSourceImportData, programId: string, source: WorkflowImportSource): boolean {
  const provenance = record(data.doc.provenance);
  const stored = provenance?.importSource as WorkflowImportOrigin | undefined;
  return provenance?.source === 'import' && !!stored && workflowOriginMatches(stored, programId, source)
    && sameRecordedOrigin(stored, data.origin, workflowOriginFields);
}

/** Reused copies keep their actual edited sections. Source hashes describe the
 * imported source version, not the editor's subsequently transformed HTML. */
export function readWorkflowImportResult(body: unknown, programId: string, source: WorkflowImportSource, preview: AuthoringSourceImportPreviewData): AuthoringSourceImportData | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportData } | null;
  const data = envelope?.data;
  if (envelope?.success !== true || !validSavedCopy(data, programId) || !isWorkflowSource(data.origin)) return null;
  if (!readWorkflowPreview({ success: true, data: preview }, programId, source) || !workflowOriginMatches(data.origin as WorkflowImportOrigin, programId, source)) return null;
  if ((data.origin as WorkflowImportOrigin).fingerprint !== preview.fingerprint || !recordedWorkflowMatches(data, programId, source)) return null;
  return data.reused || savedSectionsMatch(data, preview) ? data : null;
}
function binaryOriginMatches(origin: unknown, programId: string, source: BinaryImportSource): origin is BinaryImportOrigin {
  const row = record(origin);
  if (!row || !importUuid(programId) || !validBinarySource(source) || row.kind !== source.kind || row.programId !== programId) return false;
  const id = source.kind === 'vault' ? source.documentId : String(source.sourceId);
  return row.id === id && nonempty(row.title) && nonempty(row.fileName) && nonempty(row.mimeType) && importHash(row.sha256)
    && nullableText(row.documentType) && nullableText(row.sectionCode) && ['docx-structure', 'extracted-text'].includes(String(row.conversion));
}
/** Binary receipts require the saved rows and recorded source version too. */
export function readSourceImportResult(body: unknown, programId: string, source: AuthoringImportSource): SourceImportResult | null {
  const envelope = body as { success?: boolean; data?: AuthoringSourceImportData } | null;
  const data = envelope?.data;
  if (!validBinarySource(source) || envelope?.success !== true || !validSavedCopy(data, programId) || !binaryOriginMatches(data.origin, programId, source)) return null;
  const provenance = record(data.doc.provenance);
  const stored = provenance?.importSource;
  return provenance?.source === 'import' && binaryOriginMatches(stored, programId, source)
    && sameRecordedOrigin(stored, data.origin, binaryOriginFields) ? data : null;
}

const intakeStale = (): SourceIntakeFailure => ({ ok: false, phase: 'stale', message: 'The source, project or signed-in account changed. Reopen this source in its original project before continuing.' });
const intakeRefused = (message: string): SourceIntakeFailure => ({ ok: false, phase: 'refused', message });
const intakeUnknown = (): SourceIntakeFailure => ({ ok: false, phase: 'unknown', message: 'The working-copy save could not be confirmed. Check working documents in the original project before creating another copy.' });
function intakeCurrent(request: SourceIntakeRequest): boolean {
  try { return request.current(); } catch { return false; }
}
function pinIntakeRequest(request: SourceIntakeRequest): SourceIntakeRequest | null {
  if (!intakeCurrent(request) || !importInteger(request.actor.userId) || !importInteger(request.actor.organizationId)) return null;
  if (!nonempty(request.headers.Authorization) || request.headers['x-organization-id'] !== String(request.actor.organizationId)) return null;
  return { actor: { ...request.actor }, headers: { ...request.headers }, current: request.current };
}
function capturedCopy(data: SourceImportResult, request: SourceIntakeRequest): boolean {
  const creator = data.doc.created_by;
  return data.doc.tenant_id === request.actor.organizationId && (typeof creator === 'string' || typeof creator === 'number')
    && String(creator) === String(request.actor.userId);
}
function typedIntakeOutcome(body: unknown, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  const recovery = readAuthoringCreationRecovery(body, request.actor.organizationId, programId);
  return { ...intakeUnknown(), identifiedOutcome: true, ...(recovery ? { recovery } : {}) };
}
function failedIntakeResponse(body: unknown, status: number, create: boolean, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  if (create && hasAuthoringCreationOutcome(body)) return typedIntakeOutcome(body, programId, request);
  if (create && (status === 408 || status >= 500 || status < 400)) return intakeUnknown();
  return intakeRefused(serverMessage(body) ?? 'The source and target could not be verified. Check access and reload the source preview before retrying.');
}
function failedIntakeError(error: unknown, create: boolean, programId: string, request: SourceIntakeRequest): SourceIntakeFailure {
  if (!intakeCurrent(request)) return intakeStale();
  if (create && error instanceof ApiRequestError && hasAuthoringCreationOutcome({ code: error.code })) return typedIntakeOutcome(error.payload, programId, request);
  return error instanceof ApiRequestError ? failedIntakeResponse(error.payload, error.status, create, programId, request)
    : create ? intakeUnknown() : intakeRefused('The saved source could not be read. Check access and reload its preview.');
}
async function requestSourceIntake<T>(programId: string, payload: Record<string, unknown>, request: SourceIntakeRequest,
  create: boolean, read: (body: unknown) => T | null): Promise<SourceIntakeReply<T>> {
  if (!intakeCurrent(request)) return intakeStale();
  try {
    const response = await apiRequest('POST', '/api/authoring/import/source', payload, request.headers);
    if (!intakeCurrent(request)) return intakeStale();
    const body: unknown = await response.json().catch(() => null);
    if (!intakeCurrent(request)) return intakeStale();
    if (!response.ok || (create && hasAuthoringCreationOutcome(body))) return failedIntakeResponse(body, response.status, create, programId, request);
    const data = read(body);
    return data ? { ok: true, data } : failedIntakeResponse(body, response.status, create, programId, request);
  } catch (error) { return failedIntakeError(error, create, programId, request); }
}
function pinSource<T extends AuthoringImportSource>(source: T): T {
  return { ...source, ...(source.kind === 'csr' && source.sectionNumbers ? { sectionNumbers: [...source.sectionNumbers] } : {}) };
}
function pinPreview(preview: AuthoringSourceImportPreviewData): AuthoringSourceImportPreviewData {
  return JSON.parse(JSON.stringify(preview)) as AuthoringSourceImportPreviewData;
}
export function previewWorkflowImport(programId: string, source: WorkflowImportSource, request: SourceIntakeRequest): Promise<SourceIntakeReply<AuthoringSourceImportPreviewData>> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!importUuid(programId) || !validWorkflowSource(selected)) return Promise.resolve(intakeRefused('Choose a saved source and an existing project.'));
  return requestSourceIntake(programId, { programId, source: selected, previewOnly: true }, pinned, false, body => readWorkflowPreview(body, programId, selected));
}
export function createWorkflowImport(programId: string, source: WorkflowImportSource, preview: AuthoringSourceImportPreviewData, reason: string,
  options: { request: SourceIntakeRequest; associationReason?: string }): Promise<SourceIntakeReply<SourceImportResult>> {
  const request = pinIntakeRequest(options.request);
  if (!request) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!readWorkflowPreview({ success: true, data: preview }, programId, selected)) return Promise.resolve(intakeRefused('Reload the saved source preview before creating a working copy.'));
  const expected = pinPreview(preview);
  return requestSourceIntake(programId, { programId, source: selected, expectedFingerprint: expected.fingerprint, reason,
    ...(options.associationReason ? { associationReason: options.associationReason } : {}) }, request, true, body => {
    const data = readWorkflowImportResult(body, programId, selected, expected);
    return data && capturedCopy(data, request) ? data : null;
  });
}
export function createBinaryImport(programId: string, source: AuthoringImportSource, reason: string, request: SourceIntakeRequest): Promise<SourceIntakeReply<SourceImportResult>> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return Promise.resolve(intakeStale());
  const selected = pinSource(source);
  if (!importUuid(programId) || !validBinarySource(selected)) return Promise.resolve(intakeRefused('Choose a saved source and an existing project.'));
  return requestSourceIntake(programId, { programId, source: selected, reason }, pinned, true, body => {
    const data = readSourceImportResult(body, programId, selected);
    return data && capturedCopy(data, pinned) ? data : null;
  });
}

type IntakeInventoryRow = { id: string; title: string; readScope: 'document' | 'sections' };
function readIntakeInventory(body: unknown, programId: string): IntakeInventoryRow[] | null {
  const envelope = record(body);
  if (envelope?.success !== true || !Array.isArray(envelope.documents)) return null;
  const rows = envelope.documents as Array<Record<string, unknown>>;
  if (!rows.every(row => !!row && importUuid(row.id) && nonempty(row.title) && row.program_id === programId
    && (row.readScope === 'document' || row.readScope === 'sections'))) return null;
  if (new Set(rows.map(row => String(row.id).toLowerCase())).size !== rows.length) return null;
  return rows.map(row => ({ id: String(row.id), title: String(row.title), readScope: row.readScope as IntakeInventoryRow['readScope'] }));
}
async function readIntakePath(path: string, request: SourceIntakeRequest): Promise<SourceIntakeReply<unknown>> {
  if (!intakeCurrent(request)) return intakeStale();
  try {
    const response = await apiRequest('GET', path, undefined, request.headers);
    if (!intakeCurrent(request)) return intakeStale();
    const body: unknown = await response.json().catch(() => null);
    if (!intakeCurrent(request)) return intakeStale();
    return response.ok ? { ok: true, data: body } : intakeRefused('The working documents could not be read. Check access in the original project and try the check again.');
  } catch { return intakeCurrent(request) ? intakeRefused('The working documents could not be read. Try the check again in the original project.') : intakeStale(); }
}
function exactIntakeRecovery(attempt: SourceImportInspectionAttempt, request: SourceIntakeRequest, programId: string): AuthoringCreationRecoveryIdentity | null {
  const recovery = attempt.recovery;
  return recovery && importUuid(recovery.documentId) && recovery.organizationId === request.actor.organizationId && recovery.programId === programId
    && (recovery.creationOutcome === 'unconfirmed' || recovery.creationOutcome === 'committed') ? { ...recovery } : null;
}
function recoveredImportBody(detail: unknown, sections: unknown, recovery: AuthoringCreationRecoveryIdentity): unknown {
  const header = record(detail);
  const doc = record(header?.document);
  const rows = record(sections);
  if (header?.success !== true || doc?.id !== recovery.documentId || doc.readScope !== 'document' || doc.sourceMetadataState !== 'available'
    || rows?.success !== true || rows.readScope !== 'document') return null;
  const origin = record(record(doc.provenance)?.importSource);
  return { success: true, data: { doc, sections: rows.sections, origin, warnings: origin?.warnings, reused: true } };
}
function readRecoveredCopy(body: unknown, programId: string, source: AuthoringImportSource, preview: AuthoringSourceImportPreviewData | undefined): SourceImportResult | null {
  return isWorkflowSource(source) ? preview ? readWorkflowImportResult(body, programId, source, preview) : null
    : readSourceImportResult(body, programId, source);
}
async function inspectIdentifiedImport(target: { programId: string; source: AuthoringImportSource; preview?: AuthoringSourceImportPreviewData },
  recovery: AuthoringCreationRecoveryIdentity, request: SourceIntakeRequest, rows: IntakeInventoryRow[]): Promise<SourceIntakeReply<SourceImportResult>> {
  const { programId, source, preview } = target;
  if (!rows.some(row => row.id === recovery.documentId && row.readScope === 'document')) return intakeRefused('The identified document is not currently available as a whole document in this project.');
  const detail = await readIntakePath(authoringCurrentReadPath(recovery.documentId, programId), request);
  if (!detail.ok) return detail;
  const sections = await readIntakePath(authoringCurrentReadPath(recovery.documentId, programId, true), request);
  if (!sections.ok) return sections;
  const data = readRecoveredCopy(recoveredImportBody(detail.data, sections.data, recovery), programId, source, preview);
  return data && capturedCopy(data, request) ? { ok: true, data } : intakeRefused('The identified working copy and its recorded source could not be verified. No document was opened.');
}
/** Read-only inspection never infers a receipt from an inventory title or order. */
export async function inspectSourceImport(programId: string, source: AuthoringImportSource, attempt: SourceImportInspectionAttempt,
  request: SourceIntakeRequest): Promise<SourceImportInspection> {
  const pinned = pinIntakeRequest(request);
  if (!pinned) return intakeStale();
  const selected = pinSource(source);
  if (!importUuid(programId) || !(validWorkflowSource(selected) || validBinarySource(selected))) return intakeRefused('Choose the original saved source and project.');
  const recovery = exactIntakeRecovery(attempt, pinned, programId);
  if ((attempt.identifiedOutcome || attempt.recovery) && !recovery) return { ...intakeUnknown(), identifiedOutcome: true };
  const preview = attempt.preview ? pinPreview(attempt.preview) : undefined;
  const reply = await readIntakePath(`/api/authoring/docs?status=all&programId=${encodeURIComponent(programId)}`, pinned);
  if (!reply.ok) return reply;
  const rows = readIntakeInventory(reply.data, programId);
  if (!rows) return intakeRefused('The working-document inventory could not be verified in the original project. Try the check again.');
  const inventory = rows.map(({ id, title }) => ({ id, title }));
  if (!recovery) return { ok: true, inventory };
  const recovered = await inspectIdentifiedImport({ programId, source: selected, preview }, recovery, pinned, rows);
  if (!recovered.ok) return recovered;
  return { ok: true, inventory, data: recovered.data };
}

/**
 * The project's agency inbox: one store, one list, two screens (2026-10-17).
 *
 * There were two agency inboxes that did not know about each other. Project
 * home's Respond tab took the agency's letter into the data room and nowhere
 * else; Communication kept its own log in concept2cure_agency_communications.
 * A letter added in Respond never appeared in Communication's inbox, and a
 * communication logged there could not be drafted from its letter.
 *
 * The Communication store is the canonical record. This module is the one
 * client path to it, used by both screens:
 *   - useAgencyInbox: the list read (GET .../agency-communications), the
 *     audited write (POST, the same route Communication's "Log communication"
 *     uses) and the triage transition (PATCH .../:eventId/advance, computed
 *     server-side from the stored status).
 *   - AgencyInboxList: the inbox cards, with their triage state and actions.
 *   - draftResponseWithAna: "Draft response with AnA" hands AnA the letter
 *     itself, pinned as a source for that one turn (window.C2C_SOURCE_PINS,
 *     the data room's handoff, read once by useAnaChat). AnA drafts; nothing
 *     here claims a response was produced.
 *
 * A letter is linked to its communication by its data-room source, written
 * into linkedArtifactIds as `cre_source:<id>` (the reference the upload route
 * itself records for a source). No schema change: the column already existed.
 *
 * Each card opens the letter's questions and responses (AgencyResponses.tsx,
 * 2026-10-18): a response per question, approved by a Part 11 signature, and
 * the response package. Closing a letter with recorded questions is refused by
 * the server until every response is approved.
 *
 * Another screen can open one letter (2026-10-19): CMC / Module 3 lists the
 * program's Module 3 questions read from their letters, and each opens here,
 * on its letter, where it is worked (P-38). The list takes `openLetterId`
 * (from the navigation-params channel, consumed by CommunicationCenter), opens
 * that card, scrolls it into view and moves focus to it; a letter that is not
 * in the list is said to be so, and no other letter opens.
 */
import React from 'react';
import { I } from '../icons';
import { utcDaysUntil } from '@shared/utils/utc-day';
import { useLiveRows, EmptyState } from '../dataConnect';
import { apiRequest, serverMessage } from '@/lib/queryClient';
import { CC_SOURCE_TYPES, CC_TONE, CC_CLOSURE } from '../fixtures/commcenter';
import type { C2CFormFieldOption } from '../C2CForm';
import type { SourceRow } from './projectSources';
import type { LinkedSubmission } from '@shared/types/communication-center';
import { AgencyResponses } from './AgencyResponses';
import '../styles/commcenter-v2.css';
import { CompanyLegalCommunicationLinks } from './CompanyLegalCommunicationLinks';
import type { CompanyLegalCommunicationLink } from '@shared/company-correspondence';

/**
 * GET agency-communications row. The list read does NOT project a top-level
 * taskId (task linkage is created on POST but not returned by the GET), and
 * visibilityTier is nested under auditMetadata — both are read null-safe and
 * never fabricated. Dates arrive as ISO strings; dueDate is nullable.
 */
export interface CommRow {
  id: string;
  sourceType: string;
  communicationType: string;
  sourceChannel: string;
  linkedSectionCodes: string[];
  /** Documents the communication is about; a letter's source is `cre_source:<id>`. */
  linkedArtifactIds?: string[];
  /** The submission id as stored; read with linkedSubmission, which says whether it names one. */
  linkedSubmissionId?: string | null;
  /** The live submission of this project's program the id names, or null when it names none. */
  linkedSubmission?: LinkedSubmission | null;
  receivedDate: string;
  dueDate?: string | null;
  urgency: 'critical' | 'high' | 'medium' | 'low';
  responseRequired: boolean;
  extractedIssues: string[];
  humanReviewStatus: string;
  closureStatus: string;
  auditMetadata?: { visibilityTier?: string | null; companyLegalDocuments?: CompanyLegalCommunicationLink[] } | null;
  taskId?: string | null; // not returned by the list read; never fabricated
  _new?: boolean; // client-only optimistic marker
}

/** What the POST takes (server/routes/c2c/communication-center.ts schema). */
export interface LogCommunicationBody {
  sourceType: string;
  communicationType: string;
  sourceChannel: string;
  linkedSectionCodes: string[];
  linkedArtifactIds?: string[];
  /** A submission of this project's program; the server refuses any other. */
  linkedSubmissionId?: string;
  dueDate?: string;
  urgency: CommRow['urgency'];
  responseRequired: boolean;
  extractedIssues: string[];
  visibilityTier: string;
}

export type LogResult = { ok: true; row: CommRow } | { ok: false; detail: string };

/* Stable empty seed while the live inbox is loading / errored / project-less,
   so the re-seed effect below does not thrash. */
const EMPTY_COMMS: CommRow[] = [];

export function agencyCommsPath(projectId: string | null | undefined): string | null {
  return projectId ? '/api/concept2cure/projects/' + encodeURIComponent(projectId) + '/agency-communications' : null;
}

const LETTER_SOURCE_PREFIX = 'cre_source:';

/** The linkedArtifactIds entry that ties a communication to its letter's data-room source. */
export function letterSourceRef(sourceId: number): string {
  return LETTER_SOURCE_PREFIX + String(sourceId);
}

/** A submission as the inbox, the log form and Respond name it: title, then application type and market. */
export function submissionLabel(s: Pick<LinkedSubmission, 'id' | 'title' | 'applicationType' | 'primaryRegion'>): string {
  const where = [s.applicationType, s.primaryRegion].filter((v): v is string => Boolean(v)).map((v) => v.toUpperCase());
  return `${s.title || `Submission ${s.id}`}${where.length ? ` (${where.join(', ')})` : ''}`;
}

/**
 * What a communication's card says of its submission. A stored id that names
 * none of this project's live submissions (an older unchecked value, or a
 * submission since removed) is said as such, never shown as a link.
 */
export function submissionLinkText(c: Pick<CommRow, 'linkedSubmissionId' | 'linkedSubmission'>): string {
  if (c.linkedSubmission) return ' · concerns ' + submissionLabel(c.linkedSubmission);
  return c.linkedSubmissionId ? ' · the submission it names is not one of this project\u2019s' : '';
}

/** The data-room source ids of the letter(s) linked to a communication. */
export function letterSourceIds(c: Pick<CommRow, 'linkedArtifactIds'>): string[] {
  return (c.linkedArtifactIds ?? [])
    .map((ref) => /^cre_source:(\d+)$/.exec(String(ref))?.[1] ?? null)
    .filter((id): id is string => id != null && Number(id) > 0);
}

/**
 * The log form's letter choices: this project's data-room sources, each one
 * already linked to an inbox item listed as such and not choosable, so the
 * same letter is not logged twice. Only the title is shown; nothing is read
 * off the letter.
 */
export function letterSourceOptions(
  sources: ReadonlyArray<Pick<SourceRow, 'id' | 'title' | 'isCurrent'>>,
  comms: ReadonlyArray<Pick<CommRow, 'linkedArtifactIds'>>,
): C2CFormFieldOption[] {
  const linked = new Set(comms.flatMap((c) => letterSourceIds(c)));
  return sources.map((s) => {
    const name = s.title ?? `Source ${s.id}`;
    const superseded = s.isCurrent === false ? ' (superseded)' : '';
    return linked.has(String(s.id))
      ? { value: String(s.id), label: `${name}${superseded}: already in the inbox`, disabled: true }
      : { value: String(s.id), label: name + superseded };
  });
}

/** Only ApiRequestError has been through the envelope reduction and is safe to show. */
function thrownDetail(e: unknown): string {
  const known = (e as { name?: unknown })?.name === 'ApiRequestError';
  return known && (e as Error).message ? (e as Error).message : 'the service could not be reached';
}

/**
 * "Draft response with AnA": the communication's letter is pinned for this one
 * turn, so the draft is grounded on it rather than on whatever retrieval picks.
 * A communication with no linked document says so in the request, and clears
 * any pin left behind, so no other document is passed off as the letter.
 */
export function draftResponseWithAna(c: CommRow, onAsk: (q: string) => void): void {
  const pins = letterSourceIds(c);
  const w = window as unknown as { C2C_SOURCE_PINS?: string[] };
  if (pins.length) w.C2C_SOURCE_PINS = pins;
  else delete w.C2C_SOURCE_PINS;
  const issues = c.extractedIssues?.length ? ` Issues recorded on it: ${c.extractedIssues.join('; ')}.` : '';
  onAsk(
    `Draft a response to the agency communication "${c.communicationType}" (${c.id}) in this project's agency inbox.` +
      (pins.length
        ? " The agency's letter is attached as a source: answer each question it asks, quoting the question."
        : ' No document of the letter is linked to this communication, so work only from what is recorded on it and say what the letter would be needed for.') +
      issues +
      ' Use no question number or due date the letter does not state.',
  );
}

/**
 * The project's agency communications: the live read, seeded into local state
 * so a logged or advanced row shows the server's record without a re-read.
 */
export function useAgencyInbox(projectId: string | null, fire: (m: string, tone?: 'ok' | 'error') => void) {
  const path = agencyCommsPath(projectId);
  const live = useLiveRows<CommRow>(path);
  const seed = !path || live.loading || live.error ? EMPTY_COMMS : live.rows;
  const [comms, setComms] = React.useState<CommRow[]>(() => seed.map((c) => ({ ...c })));
  /* Adopt a new read DURING the render that sees it, not in an effect after
     it: an effect left one committed frame with the read settled (loading
     false) and the rows still the empty copy, so the inbox painted "No agency
     communications yet" and, for a letter another screen linked to, a
     role="alert" "That letter is not in this project's inbox" over a letter
     that was there (review of 2026-10-19). React re-renders before committing. */
  const [adopted, setAdopted] = React.useState<CommRow[]>(seed);
  if (adopted !== seed) {
    setAdopted(seed);
    setComms(seed.map((c) => ({ ...c })));
  }

  /* The audited write. The row adopted is the SERVER's record (real id, real
     generated task id); on failure nothing is added and the caller says so. */
  const log = React.useCallback(
    async (body: LogCommunicationBody): Promise<LogResult> => {
      if (!path) return { ok: false, detail: 'no project is selected' };
      try {
        const res = await apiRequest('POST', path, body);
        const json = await res.json().catch(() => null);
        if (!res.ok || !json?.success) {
          return { ok: false, detail: serverMessage(json) ?? `the store did not accept it (HTTP ${res.status})` };
        }
        const saved = json.data as CommRow & { generatedTaskId?: number };
        const row: CommRow = {
          ...saved,
          taskId: saved.generatedTaskId != null ? String(saved.generatedTaskId) : null,
          _new: true,
        };
        setComms((cs) => [row, ...cs.filter((c) => c.id !== row.id)]);
        return { ok: true, row };
      } catch (e) {
        return { ok: false, detail: thrownDetail(e) };
      }
    },
    [path],
  );

  /* Triage persists: the server computes the transition from the STORED status
     and writes an audit entry; the row is adopted from its answer. */
  const advance = React.useCallback(
    async (id: string) => {
      if (!path) return;
      try {
        const res = await apiRequest('PATCH', `${path}/${encodeURIComponent(id)}/advance`);
        const body = await res.json().catch(() => null);
        if (!res.ok) {
          fire('Not advanced — ' + (serverMessage(body) ?? `the server refused the change (HTTP ${res.status})`) + '. Nothing was stored.', 'error');
          return;
        }
        const row = (body as { data?: { humanReviewStatus?: string; closureStatus?: string } } | null)?.data;
        if (!row?.humanReviewStatus) {
          fire('Not advanced — the server did not confirm the new status.', 'error');
          return;
        }
        setComms((cs) =>
          cs.map((c) =>
            c.id === id
              ? { ...c, humanReviewStatus: row.humanReviewStatus as string, closureStatus: row.closureStatus ?? c.closureStatus }
              : c,
          ),
        );
        fire(`Advanced to ${String(row.humanReviewStatus).replace('_', ' ')} — recorded with an audit entry.`);
      } catch (e) {
        fire('Not advanced — ' + (e instanceof Error ? e.message : String(e)) + '. Nothing was stored.', 'error');
      }
    },
    [path, fire],
  );

  return { path, live, comms, log, advance, projectId, fire };
}

/**
 * Whole UTC calendar days from today to a date (0 on the day itself, negative
 * once it has passed); null when there is none. The same days the server's
 * overdue verdict compares (shared/utils/utc-day.ts): counted in milliseconds
 * from the browser's clock, a letter due today read "-1d" from 12:00 UTC on.
 */
export function daysTo(d: string | null | undefined, now: Date = new Date()): number | null {
  return utcDaysUntil(d, now.toISOString());
}

/**
 * A due date's day count in words: "today", "in 3 days", "4 days ago". A date
 * that has passed is said as that, never as "overdue": whether a letter is
 * overdue is the server's verdict (its questions not all approved), not the
 * calendar's.
 */
export function dueInWords(d: string | null | undefined, short = false): string | null {
  const n = daysTo(d);
  if (n === null) return null;
  if (n === 0) return 'today';
  const unit = short ? 'd' : n === 1 || n === -1 ? ' day' : ' days';
  return n > 0 ? `in ${n}${unit}` : `${-n}${unit} ago`;
}

/** Where a card opens its letter's questions and responses. */
export interface InboxResponses {
  projectId: string;
  fire: (m: string, tone?: 'ok' | 'error') => void;
  onNav?: (id: string) => void;
}

/** A request, from another screen, to open one letter (and one of its questions). */
export interface LetterOpening {
  letterId: string;
  questionId: number | null;
  /** A new request for the same letter opens it again. */
  token: number;
}

/** Opens, scrolls to and focuses a card another screen linked to; a new link for the same card does it again. */
function useLinkedOpen(targeted: boolean, token: number | undefined, setOpen: (open: boolean) => void) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (!targeted) return;
    setOpen(true);
    ref.current?.scrollIntoView?.({ block: 'start' });
    ref.current?.focus();
  }, [targeted, token, setOpen]);
  return ref;
}

/** One agency communication: what came in, its triage state and its actions. */
function AgencyInboxCard({ c, onAdvance, onAsk, onOpenTask, projectId, responses, opening }: {
  c: CommRow;
  projectId?: string | null;
  onAdvance: (id: string) => void;
  onAsk: (q: string) => void;
  onOpenTask?: () => void;
  responses?: InboxResponses;
  opening?: LetterOpening | null;
}) {
  const [open, setOpen] = React.useState(false);
  const panelId = React.useId();
  const targeted = opening?.letterId === c.id;
  const cardRef = useLinkedOpen(targeted, opening?.token, setOpen);
  const titleId = React.useId();
  const linkedNoteId = React.useId();
  /* The card a link opened takes focus, so it is a named region: its name is
     its own title plus a note that a link opened it. A name on a role-less
     div is prohibited (ARIA 1.2) and, where honoured, hides the card's due
     date, state and actions behind the label. */
  return (
    <div
      ref={cardRef}
      className="cc-comm"
      data-fresh={c._new || undefined}
      data-urgency={c.urgency}
      data-letter-id={c.id}
      tabIndex={targeted ? -1 : undefined}
      role={targeted ? 'region' : undefined}
      aria-labelledby={targeted ? `${titleId} ${linkedNoteId}` : undefined}
    >
      {targeted ? <span id={linkedNoteId} className="sr-only">opened from a link</span> : null}
      <div className="cc-comm-l">
        {/* Urgency on an agency communication was carried by the dot's tone alone. */}
        <span className={'cc-comm-dot tone-' + (CC_TONE[c.urgency] || 'idle')} aria-hidden="true" />
        <span className="sr-only">{c.urgency ? `Urgency: ${c.urgency}` : 'Urgency not set'}</span>
      </div>
      <div className="cc-comm-b">
        <div className="cc-comm-top">
          <span className="cc-comm-t" id={titleId}>{c.communicationType}</span>
          <span className="cc-comm-src">{CC_SOURCE_TYPES[c.sourceType] || c.sourceType}</span>
          {c.responseRequired && <span className="rd-chip tone-err">response required</span>}
          {/* closureStatus is nullable on the register (a row logged before
              the closure workflow existed carries none), so the chip is
              omitted rather than asserting a state. */}
          {c.closureStatus && (
            <span className={'rd-chip tone-' + (CC_CLOSURE[c.closureStatus] || 'idle')}>
              {c.closureStatus.replace(/_/g, ' ')}
            </span>
          )}
        </div>
        <div className="cc-comm-meta mono">
          {c.sourceChannel} · received {c.receivedDate}
          {c.dueDate
            ? ' · due ' + c.dueDate + (dueInWords(c.dueDate, true) != null ? ' (' + dueInWords(c.dueDate, true) + ')' : '')
            : ''}
          {/* linkedSectionCodes / extractedIssues are absent, not [], on rows
              the list read narrows or that predate the columns. */}
          {c.linkedSectionCodes?.length ? ' · §' + c.linkedSectionCodes.join(' §') : ''}
          {letterSourceIds(c).length ? ' · letter in the data room' : ''}
          {submissionLinkText(c)}
        </div>
        {c.extractedIssues && c.extractedIssues.length > 0 && (
          <ul className="cc-comm-issues">
            {c.extractedIssues.map((iss, i) => (
              <li key={i}>{iss}</li>
            ))}
          </ul>
        )}
        {projectId && <CompanyLegalCommunicationLinks projectId={projectId} recordId={c.id} kind="agency" initial={c.auditMetadata?.companyLegalDocuments} />}
        <div className="cc-comm-foot">
          {c.taskId && onOpenTask && (
            <button className="cc-comm-task" onClick={onOpenTask} title="Open in Tasking">
              {I.checkSquare} {c.taskId}
            </button>
          )}
          {c.responseRequired && c.closureStatus !== 'closed' && (
            <button className="cc-btn sm primary" onClick={() => draftResponseWithAna(c, onAsk)}>
              {I.penLine} Draft response with AnA
            </button>
          )}
          {responses && (
            <button className="cc-btn sm" aria-expanded={open} aria-controls={panelId} onClick={() => setOpen((o) => !o)}>
              {I.list} {open ? 'Hide questions & responses' : 'Questions & responses'}
            </button>
          )}
          {c.closureStatus !== 'closed' && (
            <button className="cc-btn sm" onClick={() => onAdvance(c.id)}>
              {c.humanReviewStatus === 'pending_review' ? 'Triage' : 'Close letter'}
            </button>
          )}
          {c.auditMetadata?.visibilityTier && (
            <span className="cc-comm-vis" title="Visibility tier">
              {I.eye} {c.auditMetadata.visibilityTier.replace(/_/g, ' ')}
            </span>
          )}
        </div>
        {responses && open && (
          <div id={panelId}>
            <AgencyResponses
              projectId={responses.projectId}
              letter={c}
              fire={responses.fire}
              onNav={responses.onNav}
              focusQuestionId={targeted ? opening?.questionId ?? null : null}
            />
          </div>
        )}
      </div>
    </div>
  );
}

/** The inbox cards, with their honest no-project / loading / error / empty states. */
export function AgencyInboxList({
  hasProject,
  projectId,
  loading,
  error,
  rows,
  onAdvance,
  onAsk,
  onOpenTask,
  responses,
  opening = null,
  emptyHint = 'Nothing has been logged for this project. Inbound agency letters, IRs and gateway acks appear here once captured.',
}: {
  hasProject: boolean;
  projectId?: string | null;
  loading: boolean;
  error?: string;
  rows: CommRow[];
  onAdvance: (id: string) => void;
  onAsk: (q: string) => void;
  onOpenTask?: () => void;
  /** Lets each card open its letter's questions and responses. */
  responses?: InboxResponses;
  /** A letter another screen asked to open (CMC's "Open on its letter"). */
  opening?: LetterOpening | null;
  emptyHint?: string;
}) {
  /* A letter that is not in this list (deleted, restricted from this person,
     another project's) is said to be so; no other letter is opened instead. */
  const missing = opening && !loading && !error && !rows.some((c) => c.id === opening.letterId)
    ? (
        <p className="cc-q-note" role="alert">
          That letter is not in this project's inbox, or you cannot open it.
        </p>
      )
    : null;
  if (!hasProject) {
    return (
      <EmptyState
        icon={I.fileText}
        title="Open a project to see its agency communications"
        hint="Agency letters, IRs and gateway acks are scoped to a project. Open one from Projects to load its inbox."
      />
    );
  }
  if (loading && rows.length === 0) {
    return (
      <div role="status" className="scaf-note" style={{ padding: '18px 10px' }}>
        Loading agency communications…
      </div>
    );
  }
  if (error && rows.length === 0) {
    return (
      <EmptyState
        tone="error"
        icon={I.alertTriangle}
        title="Couldn't load agency communications"
        hint="The governed agency-communications register didn't respond. Sign in and retry, or check the service is reachable."
      />
    );
  }
  if (rows.length === 0) {
    return (
      <>
        {missing}
        <EmptyState icon={I.fileText} title="No agency communications yet" hint={emptyHint} />
      </>
    );
  }
  return (
    <>
      {missing}
      <div className="cc-comms">
        {rows.map((c) => (
          <AgencyInboxCard key={c.id} c={c} projectId={projectId} onAdvance={onAdvance} onAsk={onAsk} onOpenTask={onOpenTask} responses={responses} opening={opening} />
        ))}
      </div>
    </>
  );
}

/**
 * The questions on one agency letter and our response to each (2026-10-18,
 * rows D2 and D5). Opened from a letter's card in the project's agency inbox
 * (AgencyInbox.tsx), so Communication and Project home's Respond tab show the
 * same record.
 *
 * What a person does here, and who decides what:
 *   - Record a question as the agency numbered and worded it (governed write,
 *     with a reason).
 *   - Write the response (governed write, with a reason). The revision the
 *     writer started from travels with the save, so two people cannot
 *     overwrite each other unseen.
 *   - Approve a response: the shared Part 11 EsignModal (meaning, reason,
 *     password, authenticator code when enrolled), forwarded to the route,
 *     which runs the platform's signing ceremony. The signature binds the
 *     question and the exact text shown. The person who wrote the text cannot
 *     approve it; the server says so before anyone types a password
 *     (`signRefusal`), and refuses it anyway.
 *   - Record a commitment made in a response (PMR, PMC, REMS…), into the
 *     project's commitments register under Communication's Meetings & commitments.
 *   - Withdraw a question recorded in error (governed, with a reason). It stays
 *     in the record, marked withdrawn, and needs no response.
 *   - Mark a letter that requires a response as asking nothing, with a reason,
 *     when no question is recorded on it.
 *   - Record the CTD section a question concerns, and correct it with a reason
 *     (2026-10-19). It is classification: the signature does not cover it.
 *   - Set who owns preparing a question's response, or clear it, with a reason
 *     (2026-10-19): an active member who may open the letter at its
 *     visibility, which the server checks. It replaces the free-text
 *     assignment CMC kept on its own, now read-only, question file.
 *     CMC / Module 3 lists the program's questions about its sections from it
 *     and opens each here, on its letter (P-38, P-39 item 1).
 *   - Read every text a response has had, who wrote it and why, and the
 *     signature that approved it, if one did (the history disclosure).
 *   - Download the response package once every response is approved as it
 *     stands. The server assembles it and records the export.
 *
 * This module decides nothing. A response's state (no response, draft,
 * changed after approval, approved, withdrawn), whether this person may write
 * or sign, why the letter cannot close yet, whether it is overdue, and whether
 * the package is ready are all the server's words. Nothing here says a response is approved that
 * the server did not say is, and no control is offered that the server says
 * this person would be refused.
 */
import React from 'react';
import { AgencyResponseEditor } from './AgencyResponseEditor';
import { useAuthoringReadSession } from '../editor/authoringCurrentRead';
import { ApiRequestError, apiRequest, assertApiResponseOk } from '@/lib/queryClient';
import { useAuthUser, type AuthUser } from '@/services/portal/authService';
import { EsignModal, type EsigSignedManifest, type EsignSigner } from '../../_shared/components/EsignModal';
import type { EsigMeaning } from '../../hooks/useEsignature';
import { C2CForm } from '../C2CForm';
import { EmptyState, useLiveData, type DataReadOwner } from '../dataConnect';
import { downloadBlob } from '../download';
import { I } from '../icons';
import type { CommRow } from './AgencyInbox';
import { RESPONSE_STATE_LABEL as STATE_LABEL, RESPONSE_STATE_TONE as STATE_TONE, type ResponseState } from './agencyQuestionState';

interface SignatureView {
  signatureId: number;
  signerName: string;
  signedAt: string;
  meaning: string | null;
}

interface CommitmentView {
  id: number;
  commitmentType: string;
  description: string;
  dueDate: string | null;
  regulatoryBasis: string | null;
  status: string;
  /** The register's own reading: past due and not met is overdue. */
  effectiveStatus: string;
}

interface RevisionView {
  revision: number;
  responseText: string;
  writtenByName: string | null;
  writtenAt: string;
  reason: string;
  approvedBy: SignatureView | null;
}

interface ViewerCapabilities {
  canWrite: boolean;
  writeRefusal: string | null;
  canSign: boolean;
  signAuthorityRefusal: string | null;
}

export interface AgencyQuestionView {
  id: number;
  questionRef: string;
  questionText: string;
  discipline: string | null;
  /** The CTD section the question concerns, in the repository's one spelling; null when none is recorded. */
  ctdSection?: string | null;
  /** Who owns preparing the response; null (or absent) with none. */
  ownerUserId?: number | null;
  ownerName?: string | null;
  severity: string;
  responseText: string;
  responseRevision: number;
  responseUpdatedByName: string | null;
  responseUpdatedAt: string | null;
  state: ResponseState;
  approval: SignatureView | null;
  supersededApproval: SignatureView | null;
  signRefusal: { code: string; message: string } | null;
  withdrawal: { withdrawnAt: string | null; withdrawnByName: string | null; reason: string | null } | null;
  /** Every text this response has had, newest first. */
  history: RevisionView[];
  commitments: CommitmentView[];
}

interface QuestionsPayload {
  letter: {
    id: string;
    communicationType: string;
    closureStatus: string;
    dueDate: string | null;
    responseRequired: boolean;
    /** Why the letter may not be closed now, in the server's words; null when it may. */
    closeRefusal: string | null;
    /** The server's one overdue verdict (response-logic letterOverdue), the same CMC counts. */
    overdue?: boolean;
  };
  viewer: ViewerCapabilities;
  questions: AgencyQuestionView[];
  outstanding: Array<{ questionRef: string; state: string }>;
  packageReady: boolean;
}

function isQuestionsPayload(v: unknown): v is QuestionsPayload {
  const p = v as QuestionsPayload | null;
  return Boolean(p && p.letter && p.viewer && Array.isArray(p.questions) && Array.isArray(p.outstanding));
}

/** One active member of the organisation, as GET …/projects/:projectId/team lists them. */
interface TeamMember {
  userId: number;
  name: string;
  role: string | null;
}
/** The owner select's value for "no owner". */
const NO_OWNER = 'none';

/** Refusals that mean the record moved under this person: show it as it now stands. */
const STALE_CODES = new Set(['RESPONSE_CHANGED', 'ALREADY_APPROVED', 'NOTHING_TO_SIGN', 'QUESTION_WITHDRAWN', 'LETTER_CLOSED']);
const COMMITMENT_TYPES = [
  { value: 'pmr', label: 'Postmarketing requirement (PMR)' },
  { value: 'pmc', label: 'Postmarketing commitment (PMC)' },
  { value: 'rems', label: 'REMS' },
  { value: 'meeting_commitment', label: 'Commitment' },
  { value: 'other', label: 'Other' },
];
/** §11.50: approving a response means approval, or that the signer answers for it. */
const APPROVAL_MEANINGS: ReadonlyArray<EsigMeaning> = ['approval', 'responsibility'];

function when(iso: string | null | undefined): string {
  if (!iso) return '';
  const t = new Date(iso);
  return Number.isNaN(t.getTime()) ? iso : t.toLocaleString();
}

/** Only ApiRequestError has been through the envelope reduction and is safe to show. */
function said(e: unknown): string {
  return e instanceof ApiRequestError && e.message ? e.message : 'the service could not be reached';
}

function printedSigner(u: AuthUser | null): EsignSigner | undefined {
  const name = [u?.displayName, [u?.firstName, u?.lastName].filter(Boolean).join(' '), u?.email]
    .find((v) => typeof v === 'string' && v.trim().length > 0);
  return name ? { name: name.trim(), ...(u?.email ? { email: u.email } : {}) } : undefined;
}

function signatureSentence(s: SignatureView): string {
  return `${s.signerName} on ${when(s.signedAt)}${s.meaning ? ` (${s.meaning})` : ''}, signature ${s.signatureId}`;
}

/** One question: the agency's words, our response, its approval, its history and its commitments. */
function QuestionCard({
  q,
  closed,
  busy,
  viewer,
  targeted = false,
  projectId,
  eventId,
  onNav,
  onSaved,
  onBusy,
  currentVisit,
  fire,
  onSign,
  onCommit,
  onWithdraw,
  onClassify,
  onAssign,
}: {
  q: AgencyQuestionView;
  closed: boolean;
  busy: boolean;
  viewer: ViewerCapabilities;
  /** Opened from a link to this question (CMC's "Open on its letter"): scrolled into view. */
  targeted?: boolean;
  projectId: string; eventId: string; onNav?: (id: string) => void;
  onSaved: () => void; onBusy: (busy: boolean) => void; fire: (message: string, tone?: 'ok' | 'error') => void;
  currentVisit: () => boolean;
  onSign: (q: AgencyQuestionView) => void;
  onCommit: (q: AgencyQuestionView) => void;
  onWithdraw: (q: AgencyQuestionView) => void;
  onClassify: (q: AgencyQuestionView) => void;
  onAssign: (q: AgencyQuestionView) => void;
}) {
  const itemRef = React.useRef<React.ElementRef<'li'> | null>(null);
  React.useEffect(() => {
    if (targeted) itemRef.current?.scrollIntoView?.({ block: 'center' });
  }, [targeted]);
  const [editing, setEditing] = React.useState(false);
  const textId = React.useId();
  const withdrawn = q.state === 'withdrawn';
  const writable = !closed && !withdrawn && viewer.canWrite;
  const signable = !closed && (q.state === 'drafted' || q.state === 'changed-after-approval') && viewer.canWrite;
  const signBlock = q.signRefusal?.message ?? (viewer.canSign ? null : viewer.signAuthorityRefusal);

  const startEdit = () => setEditing(true);

  return (
    <li ref={itemRef} className="cc-q" data-state={q.state} data-question-id={q.id} data-targeted={targeted || undefined}>
      <div className="cc-comm-top">
        <span className="cc-comm-t">{q.questionRef}</span>
        {q.discipline && <span className="cc-comm-src">{q.discipline}</span>}
        {q.ctdSection && <span className="cc-comm-src mono" title="CTD section">§{q.ctdSection}</span>}
        {q.ownerUserId != null && (
          <span className="cc-comm-src" title="Owns preparing the response">Owner: {q.ownerName ?? 'a member'}</span>
        )}
        <span className={'rd-chip tone-' + (q.severity === 'critical' ? 'err' : q.severity === 'major' ? 'warn' : 'idle')}>
          {q.severity}
        </span>
        <span className={'rd-chip tone-' + STATE_TONE[q.state]}>{STATE_LABEL[q.state]}</span>
      </div>
      <blockquote className="cc-q-text">{q.questionText}</blockquote>

      {withdrawn && q.withdrawal && (
        <p className="cc-q-sig">
          Withdrawn{q.withdrawal.withdrawnByName ? ` by ${q.withdrawal.withdrawnByName}` : ''}
          {q.withdrawal.withdrawnAt ? ` on ${when(q.withdrawal.withdrawnAt)}` : ''}
          {q.withdrawal.reason ? `: ${q.withdrawal.reason}` : ''}. It needs no response and is left out of the package.
        </p>
      )}

      {editing ? (
        <AgencyResponseEditor projectId={projectId} eventId={eventId} questionId={q.id} questionRef={q.questionRef}
          responseRevision={q.responseRevision} onNav={onNav} onSaved={onSaved} onCancel={() => setEditing(false)} hostCurrent={currentVisit}
          onBusy={onBusy} fire={fire} />
      ) : (
        !withdrawn && (
          <div className="cc-q-resp">
            {q.responseText.trim() ? <p className="cc-q-body">{q.responseText}</p> : <p className="cc-q-note">No response has been written.</p>}
            {q.responseRevision > 0 && (
              <p className="cc-q-meta mono">
                Revision {q.responseRevision}
                {q.responseUpdatedByName ? `, written by ${q.responseUpdatedByName}` : ''}
                {q.responseUpdatedAt ? ` on ${when(q.responseUpdatedAt)}` : ''}
              </p>
            )}
          </div>
        )
      )}

      {q.approval && <p className="cc-q-sig">Approved by {signatureSentence(q.approval)}.</p>}
      {q.state === 'changed-after-approval' && q.supersededApproval && (
        <p className="cc-q-sig" data-tone="err">
          Approved earlier by {signatureSentence(q.supersededApproval)}. The response has changed since, so it needs a new signature.
          The approved text is kept in the history below.
        </p>
      )}

      {q.commitments.length > 0 && (
        <ul className="cc-comm-issues">
          {q.commitments.map((c) => (
            <li key={c.id}>
              {c.commitmentType.toUpperCase()}: {c.description}
              {c.dueDate ? `, due ${c.dueDate}` : ''} (
              <span data-tone={c.effectiveStatus === 'overdue' ? 'err' : undefined}>{c.effectiveStatus.replace(/_/g, ' ')}</span>)
            </li>
          ))}
        </ul>
      )}

      {q.history.length > 0 && (
        <details className="cc-q-hist">
          <summary>
            History · {q.history.length} text{q.history.length === 1 ? '' : 's'}
          </summary>
          <ol className="cc-q-hist-list">
            {q.history.map((h) => (
              <li key={h.revision}>
                <p className="cc-q-meta mono">
                  Revision {h.revision}
                  {h.writtenByName ? `, written by ${h.writtenByName}` : ''} on {when(h.writtenAt)}. Reason: {h.reason}
                </p>
                <p className="cc-q-body">{h.responseText.trim() ? h.responseText : '(empty)'}</p>
                <p className="cc-q-meta">{h.approvedBy ? `Approved by ${signatureSentence(h.approvedBy)}.` : 'Not approved.'}</p>
              </li>
            ))}
          </ol>
        </details>
      )}

      {!editing && (writable || signable) && (
        <div className="cc-comm-foot">
          {writable && (
            <button className="cc-btn sm" disabled={busy} onClick={startEdit}>
              {I.penLine} {q.responseText.trim() ? 'Edit response' : 'Write response'}
            </button>
          )}
          {signable && (
            <button
              className="cc-btn sm primary"
              disabled={busy || signBlock !== null}
              aria-describedby={signBlock ? `${textId}-why` : undefined}
              onClick={() => onSign(q)}
            >
              {I.check} Approve response
            </button>
          )}
          {writable && (
            <button className="cc-btn sm" disabled={busy} onClick={() => onCommit(q)}>
              Record commitment
            </button>
          )}
          {writable && q.state !== 'approved' && (
            <button className="cc-btn sm" disabled={busy} onClick={() => onWithdraw(q)}>
              Withdraw question
            </button>
          )}
          {/* "Record" when none is recorded; "Correct" only when one is. */}
          {writable && (
            <button className="cc-btn sm" disabled={busy} onClick={() => onClassify(q)}>
              {q.ctdSection ? 'Correct section' : 'Record section'}
            </button>
          )}
          {writable && (
            <button className="cc-btn sm" disabled={busy} onClick={() => onAssign(q)}>
              {q.ownerUserId != null ? 'Change owner' : 'Set owner'}
            </button>
          )}
          {signable && signBlock && (
            <span id={`${textId}-why`} className="cc-q-note">{signBlock}</span>
          )}
        </div>
      )}
    </li>
  );
}

interface AgencyResponsesProps {
  projectId: string; letter: CommRow; fire: (m: string, tone?: 'ok' | 'error') => void;
  /** A question another screen linked to (CMC's "Open on its letter"). */
  focusQuestionId?: number | null; onNav?: (id: string) => void;
}
/** Retire all retained questions and action forms before a different visit renders. */
export function AgencyResponses(props: AgencyResponsesProps) {
  const session = useAuthoringReadSession(useAuthUser());
  const key = `${session.actor}:${session.key}:${props.projectId}:${props.letter.id}`;
  const owner = React.useRef({ key });
  if (owner.current.key !== key) owner.current = { key };
  const visit = owner.current;
  const readOwner = React.useMemo(() => ({ key, current: () => owner.current === visit && session.sameRevision() }), [key, visit, session]);
  return <ScopedAgencyResponses key={key} {...props} readOwner={readOwner} />;
}

/** The questions and responses of one admitted inbox-letter visit. */
function ScopedAgencyResponses({
  projectId,
  letter,
  fire: hostFire,
  focusQuestionId = null,
  onNav,
  readOwner,
}: AgencyResponsesProps & { readOwner: DataReadOwner }) {
  const base = `/api/concept2cure/projects/${encodeURIComponent(projectId)}/agency-communications/${encodeURIComponent(letter.id)}`;
  const [version, setVersion] = React.useState(0);
  const reload = () => { if (readOwner.current()) setVersion((v) => v + 1); };
  const fire = (message: string, tone?: 'ok' | 'error') => { if (readOwner.current()) hostFire(message, tone); };
  const read = useLiveData<QuestionsPayload>(`${base}/questions`, [base, version],
    value => isQuestionsPayload(value) && value.letter.id === letter.id, readOwner);
  const authUser = useAuthUser();
  const [busy, setBusy] = React.useState(false);
  const [adding, setAdding] = React.useState(false);
  const [committing, setCommitting] = React.useState<AgencyQuestionView | null>(null);
  const [withdrawing, setWithdrawing] = React.useState<AgencyQuestionView | null>(null);
  const [classifying, setClassifying] = React.useState<AgencyQuestionView | null>(null);
  const [assigning, setAssigning] = React.useState<AgencyQuestionView | null>(null);
  /* The organisation's active members, read only while the owner form is
     open. The server decides who may own a response (a member who may open
     this letter at its visibility) and says so if the one chosen may not. */
  const team = useLiveData<TeamMember[]>(
    assigning ? `/api/concept2cure/projects/${encodeURIComponent(projectId)}/team` : null,
    [projectId, assigning?.id ?? null],
    undefined, readOwner,
  );
  const [askingNothing, setAskingNothing] = React.useState(false);
  const [signing, setSigning] = React.useState<AgencyQuestionView | null>(null);
  /* Reload when the signing dialog closes: after a signature, or after a
     refusal that says the record moved (another save, another approval). */
  const reloadOnClose = React.useRef(false);

  const data = read.data;
  const closed = data?.letter.closureStatus === 'closed';

  const addQuestion = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    setBusy(true);
    try {
      const res = await apiRequest('POST', `${base}/questions`, {
        questionRef: v.questionRef,
        questionText: v.questionText,
        discipline: v.discipline || undefined,
        ctdSection: v.ctdSection?.trim() || undefined,
        severity: v.severity || 'major',
        reason: v.reason,
      });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      setAdding(false);
      fire(`Question ${v.questionRef} recorded, with an audit entry.`);
      reload();
    } catch (e) {
      fire(`Question not recorded: ${said(e)}. Nothing was stored.`, 'error');
    } finally {
      setBusy(false);
    }
  };


  const recordCommitment = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    if (!committing) return;
    setBusy(true);
    try {
      const res = await apiRequest('POST', `${base}/questions/${committing.id}/commitments`, {
        commitmentType: v.commitmentType,
        description: v.description,
        dueDate: v.dueDate || undefined,
        regulatoryBasis: v.regulatoryBasis || undefined,
        reason: v.reason,
      });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      fire(`Commitment recorded from ${committing.questionRef}. It is listed under Meetings & commitments.`);
      setCommitting(null);
      reload();
    } catch (e) {
      fire(`Commitment not recorded: ${said(e)}. Nothing was stored.`, 'error');
    } finally {
      setBusy(false);
    }
  };

  const withdraw = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    if (!withdrawing) return;
    setBusy(true);
    try {
      const res = await apiRequest('POST', `${base}/questions/${withdrawing.id}/withdraw`, { reason: v.reason });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      fire(`Question ${withdrawing.questionRef} withdrawn, with an audit entry. It stays in the record.`);
      setWithdrawing(null);
      reload();
    } catch (e) {
      fire(`Question ${withdrawing.questionRef} not withdrawn: ${said(e)}.`, 'error');
      if (e instanceof ApiRequestError && e.code && STALE_CODES.has(e.code)) reload();
    } finally {
      setBusy(false);
    }
  };

  /* A question's CTD section, corrected with a reason. The server normalises
     it (3.2.p.5 → 3.2.P.5) or refuses what is not a CTD code; an empty value
     clears it. The approval is not affected: the signature does not cover it. */
  const classify = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    if (!classifying) return;
    setBusy(true);
    try {
      const res = await apiRequest('PATCH', `${base}/questions/${classifying.id}`, { ctdSection: v.ctdSection?.trim() || null, reason: v.reason });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      fire(`Section of ${classifying.questionRef} recorded, with an audit entry.`);
      setClassifying(null);
      reload();
    } catch (e) {
      fire(`Section of ${classifying.questionRef} not changed: ${said(e)}.`, 'error');
      if (e instanceof ApiRequestError && e.code && STALE_CODES.has(e.code)) reload();
    } finally {
      setBusy(false);
    }
  };

  /* The owner of a question's response, set or cleared with a reason. */
  const assign = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    if (!assigning) return;
    const ownerUserId = v.owner === NO_OWNER ? null : Number(v.owner);
    setBusy(true);
    try {
      const res = await apiRequest('PATCH', `${base}/questions/${assigning.id}/owner`, { ownerUserId, reason: v.reason });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      fire(
        ownerUserId === null
          ? `Owner of ${assigning.questionRef} cleared, with an audit entry.`
          : `Owner of ${assigning.questionRef} recorded, with an audit entry.`,
      );
      setAssigning(null);
      reload();
    } catch (e) {
      fire(`Owner of ${assigning.questionRef} not changed: ${said(e)}.`, 'error');
      if (e instanceof ApiRequestError && e.code && STALE_CODES.has(e.code)) reload();
    } finally {
      setBusy(false);
    }
  };

  const markNoResponseRequired = async (v: Record<string, string>) => {
    if (!readOwner.current()) return;
    setBusy(true);
    try {
      const res = await apiRequest('POST', `${base}/no-response-required`, { reason: v.reason });
      if (!res.ok) await assertApiResponseOk(res);
      if (!readOwner.current()) return;
      fire('Letter marked as needing no response, with an audit entry. It can now be closed.');
      setAskingNothing(false);
      reload();
    } catch (e) {
      fire(`Letter not changed: ${said(e)}.`, 'error');
      reload();
    } finally {
      setBusy(false);
    }
  };

  const sign = async (input: { meaning: EsigMeaning; reason: string; password: string; totp?: string }): Promise<EsigSignedManifest> => {
    if (!readOwner.current()) throw new Error('The letter or session changed. Reopen the response before signing.');
    const q = signing!;
    try {
      const res = await apiRequest('POST', `${base}/questions/${q.id}/approve`, {
        reason: input.reason,
        meaning: input.meaning,
        password: input.password,
        ...(input.totp ? { mfaToken: input.totp } : {}),
        expectedRevision: q.responseRevision,
      });
      const body = (await res.json().catch(() => null)) as { signedAt?: string; meaning?: string; data?: { state?: string } } | null;
      if (!readOwner.current()) throw new Error('The letter or session changed. Reopen the response to read its signing result.');
      if (!res.ok || body?.data?.state !== 'approved' || !body.signedAt) {
        throw new Error('Whether the response was approved could not be confirmed. Reload before signing again.');
      }
      reloadOnClose.current = true;
      return { meaning: input.meaning, reason: input.reason, signedAt: body.signedAt };
    } catch (e) {
      if (e instanceof ApiRequestError) {
        if (e.code && STALE_CODES.has(e.code)) {
          reloadOnClose.current = true;
          throw new Error(`${e.message} Close this dialog to see the response as it now stands.`);
        }
        throw new Error(`${e.message}`);
      }
      throw e;
    }
  };

  const download = async (format: 'md' | 'docx') => {
    if (!readOwner.current()) return;
    setBusy(true);
    try {
      const res = await apiRequest('POST', `${base}/response-package`, { format });
      if (!res.ok) {
        fire('The package was not delivered. Sign in and try again.', 'error');
        return;
      }
      const sha = res.headers.get('X-Export-Sha256');
      const blob = await res.blob();
      if (!readOwner.current()) return;
      const ok = downloadBlob(`response-${letter.id}.${format}`, blob);
      fire(
        ok
          ? `Response package downloaded and recorded${sha ? ` (sha256 ${sha.slice(0, 12)}…)` : ''}.`
          : 'The package was built and recorded, but the browser refused the download.',
        ok ? 'ok' : 'error',
      );
    } catch (e) {
      fire(`The package was not assembled: ${said(e)}.`, 'error');
    } finally {
      setBusy(false);
    }
  };

  if (read.loading && !data) {
    return <div role="status" className="scaf-note">Loading the questions on this letter…</div>;
  }
  if (read.error && !data) {
    return (
      <EmptyState
        tone="error"
        icon={I.alertTriangle}
        title="Couldn't load the questions on this letter"
        hint="The responses register didn't respond. Nothing is shown rather than an incomplete list."
      />
    );
  }

  const questions = data?.questions ?? [];
  const viewer: ViewerCapabilities = data?.viewer ?? { canWrite: false, writeRefusal: null, canSign: false, signAuthorityRefusal: null };
  const asked = questions.filter((q) => q.state !== 'withdrawn');
  const approvedCount = asked.filter((q) => q.state === 'approved').length;
  const withdrawnCount = questions.length - asked.length;

  return (
    <section className="cc-qs" aria-label={`Questions and responses for ${letter.communicationType}`}>
      <div className="cc-inbox-head">
        <div className="pj-seclbl" style={{ margin: 0 }}>
          Questions and responses{' '}
          <span className="s">
            · {asked.length} question{asked.length === 1 ? '' : 's'} · {approvedCount} approved
            {withdrawnCount > 0 ? ` · ${withdrawnCount} withdrawn` : ''}
          </span>
        </div>
        {!closed && viewer.canWrite && (
          <button className="cc-btn sm" disabled={busy} onClick={() => setAdding(true)}>
            {I.plus} Record question
          </button>
        )}
      </div>

      {!closed && !viewer.canWrite && viewer.writeRefusal && (
        <p className="cc-q-note" role="note">
          You can read the questions and responses on this letter. {viewer.writeRefusal}
        </p>
      )}

      {questions.length === 0 ? (
        <p className="cc-q-note">
          No questions are recorded on this letter.
          {!data?.letter.responseRequired && ' Record each question as the agency numbered and worded it; each then takes a response and an approval.'}
        </p>
      ) : (
        <ol className="cc-q-list">
          {questions.map((q) => (
            <QuestionCard
              key={q.id}
              q={q}
              closed={closed}
              busy={busy}
              viewer={viewer}
              projectId={projectId} eventId={letter.id} onNav={onNav} onSaved={reload} onBusy={setBusy} fire={fire} currentVisit={readOwner.current}
              onSign={(x) => {
                reloadOnClose.current = false;
                setSigning(x);
              }}
              onCommit={setCommitting}
              onWithdraw={setWithdrawing}
              onClassify={setClassifying}
              onAssign={setAssigning}
              targeted={focusQuestionId === q.id}
            />
          ))}
        </ol>
      )}

      {/* The server's verdict, said as what made it: responses not approved,
          or (a response-required letter) no question to answer recorded. */}
      {!closed && data?.letter.overdue && (
        <p className="cc-q-note" data-tone="err" role="note">
          Overdue: past its due date{data.letter.dueDate ? ` (${data.letter.dueDate.slice(0, 10)})` : ''}
          {asked.length === 0 ? ', with no question recorded.' : ', with responses not approved as they stand.'}
        </p>
      )}
      {!closed && data?.letter.closeRefusal && (
        <p className="cc-q-note" role="note">
          {data.letter.closeRefusal}
        </p>
      )}
      {!closed && viewer.canWrite && data?.letter.responseRequired && asked.length === 0 && (
        <div className="cc-comm-foot">
          <button className="cc-btn sm" disabled={busy} onClick={() => setAskingNothing(true)}>
            Mark as needing no response
          </button>
        </div>
      )}

      {asked.length > 0 && (
        <div className="cc-comm-foot">
          <button className="cc-btn sm primary" disabled={busy || !data?.packageReady} onClick={() => void download('docx')}>
            {I.download} Response package (.docx)
          </button>
          <button className="cc-btn sm" disabled={busy || !data?.packageReady} onClick={() => void download('md')}>
            Markdown
          </button>
          {!data?.packageReady && data && data.outstanding.length > 0 && (
            <span className="cc-q-note">
              Available when every response is approved. Outstanding:{' '}
              {data.outstanding.map((o) => `${o.questionRef} (${STATE_LABEL[o.state as ResponseState] ?? o.state})`).join(', ')}.
            </span>
          )}
        </div>
      )}

      {adding && (
        <C2CForm
          config={{
            eyebrow: 'Agency letter · questions',
            title: 'Record a question',
            sub: `Record the question exactly as ${letter.communicationType} states it. It then takes a response and an approval.`,
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: 'Record question',
            fields: [
              { key: 'questionRef', label: 'Question number', type: 'text', placeholder: 'As the agency numbered it, e.g. Q3', required: true, half: true },
              { key: 'discipline', label: 'Discipline', type: 'select', options: ['Clinical', 'Nonclinical', 'CMC', 'Biostatistics', 'Labeling', 'Safety', 'Regulatory'], half: true },
              { key: 'severity', label: 'Severity', type: 'seg', options: ['major', 'minor', 'critical'] },
              { key: 'ctdSection', label: 'CTD section (optional)', type: 'text', placeholder: 'e.g. 3.2.P.5.1', half: true },
              { key: 'questionText', label: 'Question text', type: 'textarea', placeholder: 'Paste the question verbatim', required: true },
              { key: 'reason', label: 'Reason', type: 'text', placeholder: 'e.g. Recording the IR received 2026-10-12', required: true },
            ],
          }}
          onCancel={() => setAdding(false)}
          onSubmit={(v) => void addQuestion(v)}
        />
      )}

      {withdrawing && (
        <C2CForm
          config={{
            eyebrow: `${withdrawing.questionRef} · withdraw`,
            title: 'Withdraw this question',
            sub: `Withdraw ${withdrawing.questionRef} only if it was recorded in error. It stays in the record, marked withdrawn, needs no response and is left out of the package. This cannot be undone; record the question again if it is needed.`,
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: 'Withdraw question',
            fields: [
              { key: 'reason', label: 'Reason', type: 'text', placeholder: 'e.g. Recorded twice; the agency asked this once, as Q4', required: true },
            ],
          }}
          onCancel={() => setWithdrawing(null)}
          onSubmit={(v) => void withdraw(v)}
        />
      )}

      {classifying && (
        <C2CForm
          config={{
            eyebrow: `${classifying.questionRef} · CTD section`,
            title: classifying.ctdSection ? 'Correct the section' : 'Record the section',
            sub: classifying.ctdSection
              ? `The CTD section ${classifying.questionRef} concerns, as the agency's question cites it. Leave it empty to record none. It classifies the question; the approval does not cover it.`
              : `No CTD section is recorded for ${classifying.questionRef}. Record the one the agency's question cites. It classifies the question; the approval does not cover it.`,
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: classifying.ctdSection ? 'Correct section' : 'Record section',
            fields: [
              { key: 'ctdSection', label: 'CTD section', type: 'text', placeholder: 'e.g. 3.2.S.4.1', default: classifying.ctdSection ?? '' },
              { key: 'reason', label: 'Reason', type: 'text', placeholder: 'e.g. The agency cites the impurity specification', required: true },
            ],
          }}
          onCancel={() => setClassifying(null)}
          onSubmit={(v) => void classify(v)}
        />
      )}

      {assigning && (
        <C2CForm
          config={{
            eyebrow: `${assigning.questionRef} · Owner`,
            title: assigning.ownerUserId != null ? 'Change the owner' : 'Set the owner',
            sub:
              `Who prepares the response to ${assigning.questionRef}. ` +
              'They must be able to open this letter at its visibility. The approval does not cover it.',
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: 'Record owner',
            fields: [
              {
                key: 'owner',
                label: 'Owner',
                type: 'select',
                required: true,
                default: assigning.ownerUserId != null ? String(assigning.ownerUserId) : '',
                options: [
                  ...(assigning.ownerUserId != null ? [{ value: NO_OWNER, label: 'No owner' }] : []),
                  ...(team.data ?? []).map((m) => ({ value: String(m.userId), label: m.role ? `${m.name} (${m.role})` : m.name })),
                ],
                descStatus: team.loading
                  ? "Reading the organisation's members…"
                  : team.error
                    ? "The organisation's members could not be read, so no one can be chosen now."
                    : undefined,
              },
              { key: 'reason', label: 'Reason', type: 'text', placeholder: 'e.g. Ines leads the dissolution work', required: true },
            ],
          }}
          onCancel={() => setAssigning(null)}
          onSubmit={(v) => void assign(v)}
        />
      )}

      {askingNothing && (
        <C2CForm
          config={{
            eyebrow: 'Agency letter · no response',
            title: 'Mark as needing no response',
            sub: `${letter.communicationType} is recorded as requiring a response, and no question is recorded on it. If the letter asks nothing of you, say why; it can then be closed without a response package.`,
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: 'Mark as needing no response',
            fields: [
              { key: 'reason', label: 'Reason', type: 'text', placeholder: 'e.g. Acknowledgement letter; it asks no questions', required: true },
            ],
          }}
          onCancel={() => setAskingNothing(false)}
          onSubmit={(v) => void markNoResponseRequired(v)}
        />
      )}

      {committing && (
        <C2CForm
          config={{
            eyebrow: `${committing.questionRef} · commitment`,
            title: 'Record a commitment',
            sub: `A commitment made in the response to ${committing.questionRef}. It is tracked with its due date under Meetings & commitments, separately from the signed responses.`,
            governed: 'Recorded with your reason in the audit trail.',
            submitLabel: 'Record commitment',
            fields: [
              { key: 'commitmentType', label: 'Type', type: 'select', options: COMMITMENT_TYPES, required: true },
              { key: 'description', label: 'What was committed', type: 'textarea', required: true },
              { key: 'dueDate', label: 'Due date', type: 'date', half: true },
              { key: 'regulatoryBasis', label: 'Regulatory basis', type: 'text', placeholder: 'e.g. 21 CFR 314.81(b)(2)(vii)', half: true },
              { key: 'reason', label: 'Reason', type: 'text', required: true },
            ],
          }}
          onCancel={() => setCommitting(null)}
          onSubmit={(v) => void recordCommitment(v)}
        />
      )}

      {signing && (
        <EsignModal
          open
          action="Approve response"
          target={`${signing.questionRef}: ${letter.communicationType}`}
          targetMeta={`Your signature binds this question and the exact response text shown (revision ${signing.responseRevision}). Any later change to the text needs a new signature.`}
          meanings={APPROVAL_MEANINGS}
          defaultMeaning="approval"
          signer={printedSigner(authUser)}
          requireMfa={authUser?.mfaEnabled === true}
          onClose={() => {
            setSigning(null);
            if (reloadOnClose.current) reload();
          }}
          onSign={sign}
        />
      )}
    </section>
  );
}

/**
 * Communication Center — the regulated FDA<>client loop hub.
 *
 * Real-data standard (no mock in product). Every DATA slice renders real
 * persisted data, an honest empty state, or an honest error state — never a
 * hardcoded fixture. Self-audit of the fixture-backed slices:
 *
 *   Agency inbox  → GET /api/concept2cure/projects/:pid/agency-communications
 *                   (read, log, triage and cards: AgencyInbox.tsx, shared with
 *                   project home's Respond tab — one inbox per project)
 *                   REAL (server routes/concept2cure.ts → concept2cure_agency_communications).
 *   Meetings      → GET /api/ha-interactions/interactions   REAL (listInteractions).
 *   Commitments   → GET /api/ha-interactions/commitments     REAL (listCommitments,
 *                   the organisation's own) and, with a project open,
 *                   GET /api/concept2cure/projects/:pid/commitments (those made
 *                   in answers to its agency letters, behind project admission).
 *                   A row is CommitmentRow.tsx, its fulfilment dialog CommitmentFulfilment.tsx:
 *                   a PMR, PMC or REMS is fulfilled by a Part 11 signature that
 *                   names what met it (P-41, 2026-10-19).
 *   Authority     → GET /api/concept2cure/projects/:pid/authority-profiles
 *   profiles        REAL (server routes/concept2cure.ts → concept2cure_authority_profiles).
 *   FDA loop      → GET /api/concept2cure/projects/:pid/submission-center/items
 *                   REAL (server routes/c2c/communication-center.ts →
 *                   concept2cure_submission_center_items). The CRL round-trip
 *                   and deficiency gap analysis still have no endpoint —
 *                   MISSING → honest empty, nothing fabricated.
 *
 * NOTE on the API base: the legacy binding called `/api/communication-center/...`,
 * which is not mounted anywhere in the server (it always fell through to the
 * fixture). The real handlers live on the concept2cure router at
 * `/api/concept2cure/projects/:projectId/*`; the project id comes from the
 * runtime project channel (window.C2C_PROJECT), and parseProjectParam requires a
 * numeric id, so with no project in context the project-scoped reads show an
 * honest "open a project" empty.
 */
import React from 'react';
import { I } from '../icons';
import { AnswerLead } from '../AnswerLead';
import { useLiveRows, useLiveData, EmptyState } from '../dataConnect';
import { C2CForm } from '../C2CForm';
import { CC_SOURCE_TYPES, CC_INTERACTION_TYPES } from '../fixtures/commcenter';
import { AgencyInboxList, daysTo, dueInWords, draftResponseWithAna, letterSourceOptions, letterSourceRef, submissionLabel, useAgencyInbox, type LetterOpening } from './AgencyInbox';
import { programSubmissionsPath, type MarketSubmission } from './programSequence';
import { consumeNavParams, NAV_PARAMS_EVENT } from '../navParams';
import { isSourcesPage, sourcesUrl, type SourcesPage } from './projectSources';
import type { SurfaceViewProps } from '../surfaceViews';
import { usePublishSurfaceContext } from '../surfaceContext';
import '../styles/commcenter-v2.css';
import { C2CToast, useToast } from '../toast';
import { CompanyLegalCommunicationLinks } from './CompanyLegalCommunicationLinks';
import type { CompanyLegalCommunicationLink } from '@shared/company-correspondence';
import { ApiRequestError, apiRequest, assertApiResponseOk } from '@/lib/queryClient';
import { CommitmentFulfilDialog } from './CommitmentFulfilment';
import { CommitmentRowView, isCommitmentsPayload, type CommitmentRow, type CommitmentsPayload } from './CommitmentRow';
import { getSurfaceMeta } from '../registryModel';

/* ── Display rows, aligned to the REAL backend columns actually returned ── */

/* The agency inbox row, read, write and cards live in AgencyInbox.tsx, shared
   with project home's Respond tab: one inbox per project (2026-10-17). */

/**
 * GET /api/ha-interactions/interactions row (services/ha-interactions →
 * listInteractions). Columns are snake_case; the per-meeting question/agreed
 * counts are NOT returned by the list read and are never fabricated. Dates are
 * nullable.
 */
interface InteractionRow {
  id: number;
  interaction_type: string;
  agency: string | null;
  title: string;
  status: string;
