async function createCommunicationCenterTask(params: {
  organizationId: number;
  projectId: number;
  name: string;
  description: string;
  moduleType: string;
  priority?: 'low' | 'medium' | 'high' | 'urgent';
  dueDate?: string;
  metadata?: Record<string, unknown>;
}) {
  const values = {
    organizationId: params.organizationId,
    projectId: params.projectId,
    name: params.name,
    description: params.description,
    status: 'todo' as const,
    priority: params.priority || ('medium' as const),
    moduleType: params.moduleType,
    dueDate: params.dueDate ? new Date(params.dueDate) : undefined,
    metadata: params.metadata || {},
  };
  // `projectTasks` is typed as `any` in the schema, so drizzle widens the
  // returning() result to a union that includes a non-iterable QueryResult.
  // The runtime value is always the inserted-rows array.
  const inserted = (await db.insert(projectTasks).values(values).returning()) as any[];
  return inserted[0];
}

function mapSubmissionCenterItem(row: any, organizationId: number, projectId: number): SubmissionCenterItemRecord {
  return {
    id: row.item_id,
    organizationId,
    projectId,
    title: row.title,
    authority: row.authority,
    submissionType: row.submission_type,
    sequenceNumber: row.sequence_number ?? undefined,
    gatewayProfile: row.gateway_profile ?? undefined,
    status: row.status,
    ectdPath: row.ectd_path ?? undefined,
    dispatchReady: row.dispatch_ready,
    metadata: row.metadata || {},
    createdBy: row.created_by,
    createdAt: new Date(row.created_at).toISOString(),
    updatedAt: new Date(row.updated_at).toISOString(),
  };
}

const router = Router();

// The same chain the main router applies, in the same order.
router.use(concept2cureRateLimiter);
router.use(authMiddleware);
router.use(tenantContextMiddleware);
router.use(requireOrganizationContext);
const admitNumericCommunicationProject = projectAdmissionMiddleware();
router.param('projectId', (req, res, next, value:string) => {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value)) {
    return admitNumericCommunicationProject(req, res, next);
  }
  // A v2 URL names a program. Admit that exact private parent on the current
  // request connection before passing its verified integer anchor to the
  // existing project read/write policy and record handlers.
  void resolveCommunicationProject(req).then(projectId => {
    req.params.projectId = String(projectId);
    return admitNumericCommunicationProject(req, res, next);
  }).catch(error => {
    const refusal = error instanceof ProgramReadAccessError ? error
      : new ProgramReadAccessError(503, 'PROJECT_ACCESS_UNAVAILABLE', 'Current project access could not be verified. No project data was supplied.');
    sendError(res, refusal.status, refusal.message, undefined, refusal.code);
  });
});

